import{_ as o,l as E,o as t,c as i,v as e,p as l,x as r,d as s,i as B,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"行业/国家中性组合","description":"","frontmatter":{"title":"行业/国家中性组合","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/industry-country-neutral.md","filePath":"quant/industry-country-neutral.md","lastUpdated":1789023840000}'),A={name:"quant/industry-country-neutral.md"};function h(u,a,d,c,C,D){const n=E("Mermaid");return t(),i("div",null,[a[1]||(a[1]=e('<h1 id="行业-国家中性组合" tabindex="-1">行业/国家中性组合 <a class="header-anchor" href="#行业-国家中性组合" aria-label="Permalink to &quot;行业/国家中性组合&quot;">​</a></h1><div class="epigraph"><p>全球股票收益同时被行业与国家切开；组合若只在一个分类上净零，另一分类上的赌注仍会主导盈亏。</p><footer>—— 对照 Heston and Rouwenhorst, Journal of Financial Economics, 1994，以及全球风险模型里行业与国家因子并存的工程</footer></div><p><a href="/quant/industry-neutral">行业中性</a> 处理的是信号层：描述子要先拿掉板块均值，才谈得上在测选股而不是板块轮动。本篇把同一要求写到<strong>持仓</strong>上，并且加上国家：全球主动组合的 \\(w\\) 满足行业与国家（相对基准或相对零）的暴露约束。Heston 与 Rouwenhorst（1994）表明，国家与行业都解释收益共变，谁主谁次随样本变；Griffin（2002）等后续工作说明单靠行业不能吸收国别。Barra GEM 一类把两套哑变量都放进风险模型。优化器若只钉行业，日本银行与美国银行的相对权重仍是国别赌注；只钉国家，全球银行板块仍能把组合变成金融 beta。本篇写双重中性的线性代数、共线性、与 <a href="/quant/long-short-constraints">多空约束</a> 的自由度冲突，以及它如何补 <a href="/quant/markowitz">Markowitz</a> 的无结构二次型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全球池里，协方差的块结构至少有两套：按 GICS / 申万的行业块，按上市国或风险国的国家块。无约束均方或平坦 <a href="/quant/erc">ERC</a> 会在高波动、高相关的块里重复下注，事后归因发现「alpha」其实是超配美国科技或空头欧洲银行。基准（MSCI World、ACWI）有自己的行业与国家权重；主动组合的相对权重 \\(w-w_b\\) 若在这些方向上不受约束，跟踪误差预算会被两个粗因子吃光，选股的广度用不上。</p><p>中性要回答三句：相对谁（零还是基准）、用哪套分类（行业几级、国家还是货币）、紧还是带状（精确 \\(D^\\top(w-w_b)=0\\) 还是盒约束）。信号中性不等于持仓中性：行业内 z-score 之后，若某行业可交易名字少、头部权重大，优化器仍会漏出行业暴露。全球再叠加国家，漏出可以发生在两个轴上。问题是把分类矩阵写进同一套 QP，并处理「瑞士制药」「日本车」这类行业–国家高度缠绕导致的秩亏。</p><h3 id="一个国家因子不是一个货币因子" tabindex="-1">一个国家因子不是一个货币因子 <a class="header-anchor" href="#一个国家因子不是一个货币因子" aria-label="Permalink to &quot;一个国家因子不是一个货币因子&quot;">​</a></h3><p>国家暴露常用上市地或总部。对投资者，未对冲的收益还含货币。钉国家权重中性，未对冲组合仍有外汇；对冲到基准货币后，国家因子更多是本地股票风险。两者必须声明。新兴市场里「国家」往往强于行业；发达市场科技周期里行业可以更强。Heston–Rouwenhorst 的方差分解给出的是样本事实，不是让你只选一个轴做中性的许可证——两个轴在风险模型里都显著时，组合层也应都钉，除非跟踪误差预算明确把某一轴当成观点。</p><p><span class="marginnote">「行业中性」在 A 股单市场里已经够用，因为国家轴退化成常数。一旦股票池跨港、美、日，只做申万中性会把国别 beta 当成选股。全球产品复制国内中性代码，是最常见的漏约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设 \\(D\\) 为 \\(N\\times G\\) 行业载荷（哑变量或市值加权隶属），\\(C\\) 为 \\(N\\times K\\) 国家载荷。基准 \\(w_b\\)。紧中性：</p> \\[D^\\top(w-w_b)=0,\\qquad C^\\top(w-w_b)=0, \\]<p>再加预算、<a href="/quant/long-short-constraints">多空</a>、换手。\\(D,C\\) 的列与 \\(\\mathbf{1}\\) 线性相关（行业哑变量之和是全 1，国家亦然），必须对各表丢掉一列，或改成相对某一参照国 / 参照行业。行业与国家交叉（几乎所有韩国股票都在少数行业）时，\\([D\\ C]\\) 进一步秩亏，求解器报约束冲突或任意分配交叉格点上的权重。实务用盒约束 \\(|D^\\top(w-w_b)|\\le \\bar d\\)，给测量误差与分类变更留空隙，也给优化器留自由度去实现 alpha。</p><p>嵌套分类：先国家，再国家内行业（或先全球行业，再行业内国家）。约束写成嵌套：每个国家块内行业相对该国基准中性。自由度消耗更清晰，交叉格点（韩国科技）成为一层显式单元，可以单独设盒。风险模型若已有行业与国家因子，中性约束应与模型的因子定义一致，否则优化器钉的是 GICS，风险报告用的是 Barra 行业，中性在归因里「漏」出来。</p><h3 id="信号层与持仓层不要只做一层" tabindex="-1">信号层与持仓层不要只做一层 <a class="header-anchor" href="#信号层与持仓层不要只做一层" aria-label="Permalink to &quot;信号层与持仓层不要只做一层&quot;">​</a></h3><p>信号层行业–国家回归残差，减少 \\(\\alpha\\) 在粗因子上的投影，降低优化器与约束的对抗。若 \\(\\alpha\\) 仍含巨大国家均值，紧中性会把实现组合打到约束边界，转移系数很低——你在付中性的 IR 折扣去对冲一个本该在信号里删掉的暴露。反过来，只做信号中性、持仓不钉，头部名字与流动性约束仍会重建暴露。完整栈：描述子双重残差 → 风险模型含行业与国家 → 优化器盒约束与模型对齐 → 归因用同一套 \\(D,C\\)。</p><p>相对基准还是相对零：多头基金通常相对基准（跟踪误差产品）；美元中性多空常相对零（绝对收益）。相对零的全球多空若国家权重不钉，会变成国别宏观；若钉零又钉行业零，在 \\(N\\) 不够大时可行集很瘦，接近「每个格子里自己多空」，广度下降、换手上升。应检查每个行业–国家格子里的可交易只数，格子太小就合并（亚洲其他、全球公用）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把主动权重投影到 \\(D\\) 与 \\(C\\) 的正交补上：粗因子方向的 alpha 被扔掉，残余方向上的 \\(\\Sigma^{-1}\\alpha\\) 才被实现。跟踪误差里行业与国家的贡献被压到盒内，剩余预算分给风格与选股。代价是：真观点若就是「超配日本」或「超配全球银行」，中性会删掉它——观点应走 <a href="/quant/bl-views">Black-Litterman</a> 或显式因子倾斜，而不是假装做选股再抱怨中性杀了收益。</p><p>共线性机制：当某行业高度集中于某国，钉行业净零与钉国家净零近似同一约束，影子价格不稳定，权重在格子内的分配对数值噪声敏感。这时应降维：合并格子、或只钉更粗的轴、或把该格的净暴露当成允许的主动因子并给限额。HRP 若在原始相关上聚类，树可能按国家先切，与全球行业中性冲突；残差相关上的 HRP 才与双重中性兼容。</p><p><span class="marginnote">分类会变：公司改行业、重上市改国家、GICS 修订。中性是对<strong>当日分类矩阵</strong>而言的。历史回测必须用点时分类，否则会用未来的行业归属去中性过去的组合，这是另一种前视。</span></p><h3 id="与风险预算、erc-的接口" tabindex="-1">与风险预算、ERC 的接口 <a class="header-anchor" href="#与风险预算、erc-的接口" aria-label="Permalink to &quot;与风险预算、ERC 的接口&quot;">​</a></h3><p>平坦个股 ERC 在双重中性下往往不可行或变得极歪：等贡献要给每只 \\(1/N\\)，中性要块净零，两者抢 \\(w\\)。应改为：在行业 / 国家因子上做风险预算或把这些因子的贡献钉在盒内，个股层只做中性约束下的残差风险最小化或残差 ERC。最大分散同理。Markowitz / BL 在正交补上做切点，粗因子的 \\(\\mu\\) 用均衡或显式观点，不要让历史国别均值进入选股 \\(\\alpha\\)。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要只钉行业或只钉国家还叫全球中性。不要用等权哑变量中性去跟踪市值基准——应对 \\(D,C\\) 做市值加权隶属，或直接钉相对 \\(w_b\\) 的暴露。不要在格子只数不足时强行双重精确中性。不要把货币对冲当成国家中性已经完成。多头约束与双重中性一起，空头不可用时，某些格子无法平衡，只能放宽盒或缩小股票池。</p><p>中性不处理风格：价值、动量、规模仍可在行业–国家正交补里堆成巨大暴露。需要风格中性时，把 \\(B\\) 的风格列也加进约束，自由度进一步下降，必须有足够的个股残差 alpha，否则基金变成「约束满足器」。评价双重中性应看：相对基准的行业 / 国家 TE 贡献、选股 Brinson 的组内项、以及转移系数；只看中性后夏普，看不见你为中性付了多少 IR。</p><p><span class="marginnote">Heston–Rouwenhorst 分解的是收益共变，不是最优约束集合。样本里国家更强，并不意味着必须把行业盒放得更宽——那是风险预算决策。分解提供先验，约束宽度由产品的跟踪误差章程决定。</span></p>',27)),(t(),l(p,null,{default:r(()=>[B(n,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALPHA%5B%22%E4%BF%A1%E5%8F%B7%20%CE%B1%22%5D%20--%3E%20RES%5B%22%E8%A1%8C%E4%B8%9A%2B%E5%9B%BD%E5%AE%B6%E6%AE%8B%E5%B7%AE%E5%8C%96%22%5D%0A%20%20W%5B%22%E6%8C%81%E4%BB%93%20w%22%5D%20--%3E%20DD%5B%22D'(w-wb)%20%E8%A1%8C%E4%B8%9A%E7%9B%92%22%5D%0A%20%20W%20--%3E%20CC%5B%22C'(w-wb)%20%E5%9B%BD%E5%AE%B6%E7%9B%92%22%5D%0A%20%20RANK%5B%22D%20%E4%B8%8E%20C%20%E5%85%B1%E7%BA%BF%20%2F%20%E6%A0%BC%E5%AD%90%E7%A8%80%E7%96%8F%22%5D%20--%3E%20RELAX%5B%22%E4%B8%A2%E5%88%97%2C%20%E5%B5%8C%E5%A5%97%2C%20%E6%94%BE%E5%AE%BD%E5%B8%A6%22%5D%0A%20%20ONLYI%5B%22%E5%8F%AA%E9%92%89%E8%A1%8C%E4%B8%9A%22%5D%20--%3E%20LEAKC%5B%22%E6%BC%8F%E5%87%BA%E5%9B%BD%E5%88%AB%E8%B5%8C%E6%B3%A8%22%5D%0A%20%20ONLYC%5B%22%E5%8F%AA%E9%92%89%E5%9B%BD%E5%AE%B6%22%5D%20--%3E%20LEAKI%5B%22%E6%BC%8F%E5%87%BA%E5%85%A8%E7%90%83%E6%9D%BF%E5%9D%97%22%5D%0A%20%20RES%20--%3E%20QP%5B%22QP%20%E5%9C%A8%E6%AD%A3%E4%BA%A4%E8%A1%A5%E4%B8%8A%E9%85%8D%E7%BD%AE%22%5D%0A%20%20DD%20--%3E%20QP%0A%20%20CC%20--%3E%20QP%0A%20%20VIEW%5B%22%E7%9C%9F%E8%A7%82%E7%82%B9%E6%98%AF%E5%9B%BD%E5%88%AB%E6%88%96%E8%A1%8C%E4%B8%9A%22%5D%20--%3E%20BL%5B%22%E8%B5%B0%20BL%20%2F%20%E5%9B%A0%E5%AD%90%E5%80%BE%E6%96%9C%2C%20%E4%B8%8D%E8%A6%81%E5%81%87%E8%A3%85%E9%80%89%E8%82%A1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全球组合的持仓中性应同时约束行业与国家暴露（相对基准或相对零）；只钉一轴会漏出另一轴的宏观赌注。</li><li>信号残差化与持仓盒约束要齐做；分类须与风险模型、归因一致，并用点时隶属。</li><li>行业–国家交叉导致秩亏与影子价格不稳，用嵌套格子、合并稀疏格、盒约束而不是双重精确等式。</li><li>真的行业或国别观点应走 Black-Litterman 或显式倾斜，中性删的是未声明的粗暴露。</li><li>与 ERC / HRP / 多头约束同时开时，先保证可行集，再在残差风险上配置。</li><li>出处：Heston &amp; Rouwenhorst, <em>Journal of Financial Economics</em>, 1994；Griffin, <em>Review of Financial Studies</em>, 2002；全球风险模型中的行业与国家因子见 Barra GEM 一类文档；信号层对照 <a href="/quant/industry-neutral">行业中性</a>。</li></ul>',2))])}const f=o(A,[["render",h]]);export{_ as __pageData,f as default};
